PortForward fwd = new PortForward(); 

List<Integer> ports = new ArrayList<>();
int localPort = 8080;
int targetPort = 8080;
ports.add(targetPort);
final PortForward.PortForwardResult result = 
    fwd.forward("some-namespace", "my-pod", ports);
